-- =====================================================================
-- Esva boots 首页改版：照 getjolt.fr 的结构重写装修内容（只对 esvafit 站有效）
-- 2026-09-21
-- =====================================================================
--
-- 背景：这个站的装修内容一直是**统领时代**的那一份（硅胶管 / 气泵 / 线束），
-- 只有站名被改成了 Esva boots。首页 slogan 是「Precision Airflow and Power
-- Components」，联系方式是天津静海的地址、电话和 sales@tonglingshidai.com ——
-- 一个恢复靴品牌的官网上写着另一家公司的联系方式。
--
-- 本脚本把整份 contentjson 换成 Esva boots 自己的内容，六种语言
-- （en / fr / ru / es / ja / zh）全部写齐，结构照 getjolt.fr：
--
--   Banner → 承诺横条 → 三栏特色 → 主推商品 → 三个使用场景
--          → 顾客评价 → 合作方 → 关于我们 → 常见问题 → 全球布局 → 询盘
--
-- 后四块里 **承诺横条 / 顾客评价 / 合作方 / 常见问题是 2026-09-21 新增的区块**，
-- 需要配套的代码（前台 index.vue、后端 SiteOpenService#compose、管理台
-- station-shared/DecorateForm.vue）。只跑这个脚本、不发代码的话，那四块不会渲染，
-- 其余部分照常显示。
--
-- ---------------------------------------------------------------------
-- 哪些东西**刻意留空**
-- ---------------------------------------------------------------------
--
--   · 顾客评价（reviews）—— 有区块文案，但一条评价、一个分数都没有，而且在 off 里。
--     评分和评价条数编不得：那是对消费者的虚假陈述，而且 Google 对「自报评分」
--     的处置是整站结构化数据降权。拿到真实评价后在管理台填上再打开。
--   · 合作方（partners）—— 同上，在 off 里。没有授权就把球队徽标摆上首页是商标侵权。
--   · 全球布局（reach）—— 在 off 里。库里那份是天津总部 + 9 个外贸目的地，
--     是统领的出口图，和这个站没关系。
--   · 关于我们的配图 —— 不写。原来那张 about-factory.jpg 是化学实验室
--     （统领的硅胶配方实验室）。不写的话前台自动退成一张整宽文字卡，不会留空框。
--   · 联系地址 / 电话 / WhatsApp —— 不写。原来那三项是天津静海统领时代的，
--     留一个错的地址比空着糟得多。邮箱填的是本站询盘通知箱。
--
-- ⚠ 承诺横条前三条（两年保修 / 全球配送 / 30 天退换）是**对外承诺**，
--   买家会拿它们主张权利。发布前必须确认有对应的售后流程，做不到就在管理台改掉。
--   第四条「先报价后付款」是从代码本身能验证的（本站不收款，见 cart 的文案）。
--
-- ---------------------------------------------------------------------
-- 跑之前 / 跑之后
-- ---------------------------------------------------------------------
--
--   备份：  mysqldump 不必，取一列就够
--           SELECT contentjson FROM u_s_siteinfo WHERE id = 1;   -- 存成文件
--   跑完：  systemctl restart station-console
--           ⚠ 必须重启。站点档案缓存在进程里，不重启的话库改了、页面不变。
--   回滚：  把备份那份写回 contentjson，再重启一次。
--
-- ⚠ 反斜杠在下面是**成对**出现的（\n）。那是 JSON 里的分段符，MySQL 解一层、
--   JSON 解一层，少写一个反斜杠整份 JSON 就非法了。
-- =====================================================================

UPDATE `u_s_siteinfo`
SET `contentjson` = '{"v":4,"logo":"/files/deco/logo.jpg","hero":{"slides":[{"id":"s1","image":"/files/deco/home-hero.jpg"}]},"nav":[{"id":"n1","url":"/"},{"id":"n2","url":"/products"},{"id":"n3","url":"/#about"},{"id":"n4","url":"/#faq"},{"id":"n5","url":"/#inquiry"}],"highlights":[{"id":"h1","icon":"◎"},{"id":"h2","icon":"◷"},{"id":"h3","icon":"⊞"}],"bento":{"statValue":"20"},"capabilities":[{"id":"c1","icon":"↻"},{"id":"c2","icon":"⚡"},{"id":"c3","icon":"✚"}],"trust":{"items":[{"id":"t1","icon":"⛉"},{"id":"t2","icon":"✈"},{"id":"t3","icon":"↩"},{"id":"t4","icon":"✎"}]},"faq":{"items":[{"id":"q1"},{"id":"q2"},{"id":"q3"},{"id":"q4"},{"id":"q5"},{"id":"q6"},{"id":"q7"},{"id":"q8"}]},"contact":{"email":"3393314090@qq.com"},"order":["hero","trust","bento","products","caps","reviews","partners","about","faq","reach","inquiry"],"off":["reviews","partners","reach"],"i18n":{"en":{"companyName":"Esva boots","slogan":"Recovery · Care · Performance","seoTitle":"Esva boots — Recovery Boots and Compression Therapy","seoDescription":"Pressotherapy recovery boots for heavy, tired legs. Sequential compression from the ankle upward, twenty-minute sessions, sized by inside-leg length. We quote the full price including freight before anything is paid.","hero":{"eyebrow":"Recovery in motion","title":"Muscle recovery, made for everyone","subtitle":"Pressotherapy boots that move fluid out of tired legs, from the ankle upward, in about twenty minutes. The equipment that used to live in a clinic — sized for your living room.","btn1":"See the range","btn2":"Ask us a question"},"bento":{"title":"What makes a recovery boot work","lead":"Three things decide whether you will still be using it in a month.","statLabel":"minutes per session"},"products":{"title":"The Esva range","lead":"Boots, sleeves and the control unit that drives them."},"caps":{"title":"Three reasons people use it","lead":"The same twenty minutes, for quite different reasons."},"reviews":{"title":"What our customers say","lead":"Reviews from people who use our equipment."},"partners":{"title":"Teams and athletes","lead":"Clubs and professionals who train with Esva boots."},"faq":{"title":"Frequently asked questions","lead":"Sizing, sessions, ordering — the questions we are asked most."},"inquiry":{"title":"Ask us anything","lead":"Sizing, lead times, a quote for several units — write to us and we will come back to you."},"about":{"title":"About Esva boots","content":"Pressotherapy is not new. It has been in physiotherapy clinics and professional team rooms for decades, in the form of a machine nobody could take home and few could afford to hire twice a week.\\n\\nEsva boots exists to close that gap. The same sequential compression, in equipment you keep in a cupboard and use on a Tuesday evening — priced so that the second session costs nothing.\\n\\nWe would rather explain what the equipment does not do than oversell what it does. Compression moves fluid and relieves heaviness. It does not treat a medical condition, and anyone with one should ask a doctor first. That answer loses us a few sales and keeps the ones worth having."},"contact":{"address":""},"navText":{"n1":{"title":"Home"},"n2":{"title":"Products"},"n3":{"title":"About"},"n4":{"title":"FAQ"},"n5":{"title":"Contact"}},"highlightText":{"h1":{"title":"Sequential compression","desc":"Chambers inflate in order from the ankle upward, so fluid moves in one direction instead of being pressed from both ends at once. That sequence is the whole difference between pressotherapy and an ordinary squeeze."},"h2":{"title":"Twenty minutes, not an appointment","desc":"Short enough to do after training, or on the sofa in the evening. A recovery routine only survives past the second week if it fits the evening you actually have."},"h3":{"title":"Sized to real legs","desc":"Boots are cut by inside-leg length, not by shoe size or by height. A boot that stops halfway up the calf cannot do anything for a thigh, which is where most of the heaviness sits."}},"capText":{"c1":{"title":"Recover","desc":"Relieve heavy, tired legs after a long run, a match, or a day spent standing. Twenty minutes with the legs worked through does what an hour of simply putting them up does not."},"c2":{"title":"Perform","desc":"Turn around faster between sessions. Recovery is the part of training that quietly decides how much of tomorrow you can actually use."},"c3":{"title":"Relieve","desc":"For legs that feel heavy every evening — after standing work, after a long flight, or simply by the end of the day. Comfort, not a medical treatment: see the questions below."}},"trustText":{"t1":{"title":"Two-year warranty","desc":"Control unit and garments."},"t2":{"title":"Worldwide shipping","desc":"Tracked, with duties quoted up front."},"t3":{"title":"30 days to change your mind","desc":"Unused and in its original packaging."},"t4":{"title":"A quotation before you pay","desc":"Nothing is charged on this site. Send your list and we reply with the full price, freight included."}},"faqText":{"q1":{"q":"How do I choose the right size?","a":"Each product page lets you pick the size, and the size you pick is carried through to the quotation.\\n\\nPut your measurement in the message box when you send the request — we confirm the size before quoting. It is worth doing even when the length looks unambiguous: the right size usually depends on the circumference of the thigh as well, which a length on its own does not capture."},"q2":{"q":"How long is a session, and how often should I use it?","a":"A session is normally twenty to thirty minutes. Once a day is enough for most people, and after training is the most common moment.\\n\\nStart at the lowest pressure that still feels like something is happening, and stay there for the first week. Compression that feels uncomfortable is not working better — discomfort is the point at which you stop doing it every day, and the routine is worth more than any single session."},"q3":{"q":"Can I use it if I have a medical condition?","a":"Ask your doctor first. This is equipment for comfort and recovery, not a medical device, and we are not in a position to advise on a condition we cannot see.\\n\\nCompression is generally not used where there is a known or suspected blood clot, an acute infection or inflammation in the leg, an unhealed fracture, severe heart or kidney failure, or during pregnancy without medical advice. If any of those apply, do not order on the strength of this page — speak to a clinician."},"q4":{"q":"How do I order? Do I pay on this site?","a":"You do not pay anything on this site, and no card details are ever collected here.\\n\\nAdd the items you are interested in to your request list and send it. We reply with a full quotation — the equipment, the freight to your address, and any duties we can establish in advance. Payment terms are agreed with you directly afterwards. Sending a request costs nothing and commits you to nothing."},"q5":{"q":"Which currency are prices in?","a":"Prices are set in pounds sterling. You can switch the display to US dollars, euros, Chinese yuan, Japanese yen or Hong Kong dollars using the selector in the header.\\n\\nThose are conversions for reading convenience only, at a rate that moves. The quotation, and the figure you are actually asked to pay, is in pounds sterling."},"q6":{"q":"How do I look after the boots?","a":"Wipe the inside with a damp cloth after use and let the boots dry open — most of what shortens the life of a garment is being zipped away damp.\\n\\nDo not machine wash them and do not put them in a dryer: the chambers are welded, and heat and tumbling are what break the welds. Store them loosely rolled rather than folded along the same crease every time, and never leave the hoses kinked under something heavy."},"q7":{"q":"Do you supply clubs, clinics and gyms?","a":"Yes. Tell us how many units you need and roughly how they will be used — a physiotherapy room and a gym floor are not the same requirement — and we will quote for the whole set.\\n\\nFor multiple units it is usually worth talking about the number of control units separately from the number of garments, because that is where most of the cost sits and where most of the saving is."},"q8":{"q":"How do I check on a request I have already sent?","a":"Every request gets a reference code, which is in the confirmation you see when you send it and in the email that follows.\\n\\nUse “Find order” with that code and the email address you sent it from, or sign in if you created an account — the account page lists every request with its current status."}}},"fr":{"companyName":"Esva boots","slogan":"Récupération · Soin · Performance","seoTitle":"Esva boots — Bottes de récupération et pressothérapie","seoDescription":"Bottes de pressothérapie pour jambes lourdes et fatiguées. Compression séquentielle de la cheville vers le haut, séances de vingt minutes, tailles selon la longueur de jambe. Nous établissons le prix complet, transport inclus, avant tout paiement.","hero":{"eyebrow":"Recovery in motion","title":"La récupération musculaire, à la portée de tous","subtitle":"Des bottes de pressothérapie qui font remonter les fluides des jambes fatiguées, de la cheville vers le haut, en une vingtaine de minutes. Le matériel qui vivait en cabinet — à la taille de votre salon.","btn1":"Voir la gamme","btn2":"Poser une question"},"bento":{"title":"Ce qui fait une botte de récupération efficace","lead":"Trois choses décident si vous l’utiliserez encore dans un mois.","statLabel":"minutes par séance"},"products":{"title":"La gamme Esva","lead":"Bottes, manchons et l’unité de commande qui les alimente."},"caps":{"title":"Trois raisons de l’utiliser","lead":"Les mêmes vingt minutes, pour des raisons très différentes."},"reviews":{"title":"Ce que disent nos clients","lead":"Les avis de celles et ceux qui utilisent nos équipements."},"partners":{"title":"Équipes et athlètes","lead":"Clubs et professionnels qui s’entraînent avec Esva boots."},"faq":{"title":"Questions fréquentes","lead":"Tailles, séances, commande — les questions qui reviennent le plus."},"inquiry":{"title":"Posez-nous vos questions","lead":"Tailles, délais, devis pour plusieurs unités — écrivez-nous, nous vous répondons."},"about":{"title":"À propos d’Esva boots","content":"La pressothérapie n’a rien de nouveau. Elle est dans les cabinets de kinésithérapie et les salles de soins des équipes professionnelles depuis des décennies, sous la forme d’une machine que personne ne pouvait rapporter chez soi et que peu pouvaient se permettre de louer deux fois par semaine.\\n\\nEsva boots existe pour combler cet écart. La même compression séquentielle, dans un matériel que l’on range dans un placard et que l’on utilise un mardi soir — à un prix tel que la deuxième séance ne coûte rien.\\n\\nNous préférons expliquer ce que le matériel ne fait pas plutôt que survendre ce qu’il fait. La compression fait circuler les fluides et soulage la lourdeur. Elle ne traite pas une pathologie, et toute personne concernée doit d’abord consulter un médecin. Cette réponse nous coûte quelques ventes et nous garde celles qui valent la peine."},"contact":{"address":""},"navText":{"n1":{"title":"Accueil"},"n2":{"title":"Produits"},"n3":{"title":"À propos"},"n4":{"title":"FAQ"},"n5":{"title":"Contact"}},"highlightText":{"h1":{"title":"Compression séquentielle","desc":"Les chambres se gonflent dans l’ordre, de la cheville vers le haut : les fluides remontent dans un seul sens au lieu d’être pressés des deux côtés à la fois. Cette séquence, c’est toute la différence entre la pressothérapie et une simple compression."},"h2":{"title":"Vingt minutes, pas un rendez-vous","desc":"Assez court pour le faire après l’entraînement, ou le soir sur le canapé. Une routine de récupération ne passe la deuxième semaine que si elle tient dans la soirée dont vous disposez vraiment."},"h3":{"title":"Des tailles pour de vraies jambes","desc":"Les bottes se choisissent à la longueur de jambe, pas à la pointure ni à la taille. Une botte qui s’arrête au milieu du mollet ne peut rien faire pour une cuisse — et c’est là que se loge l’essentiel de la lourdeur."}},"capText":{"c1":{"title":"Récupérer","desc":"Soulager des jambes lourdes après une sortie longue, un match, ou une journée debout. Vingt minutes de travail sur les jambes font ce qu’une heure jambes surélevées ne fait pas."},"c2":{"title":"Performer","desc":"Enchaîner plus vite entre deux séances. La récupération est la partie de l’entraînement qui décide, sans bruit, de ce que vous pourrez vraiment faire demain."},"c3":{"title":"Soulager","desc":"Pour des jambes lourdes tous les soirs — travail debout, long vol, ou simplement la fin de journée. Du confort, pas un traitement médical : voir les questions ci-dessous."}},"trustText":{"t1":{"title":"Garantie 2 ans","desc":"Unité de commande et manchons."},"t2":{"title":"Livraison dans le monde entier","desc":"Suivie, droits de douane chiffrés à l’avance."},"t3":{"title":"30 jours pour changer d’avis","desc":"Produit non utilisé, dans son emballage d’origine."},"t4":{"title":"Un devis avant tout paiement","desc":"Rien n’est débité sur ce site. Envoyez votre liste, nous répondons avec le prix complet, transport inclus."}},"faqText":{"q1":{"q":"Comment choisir la bonne taille ?","a":"Chaque fiche produit vous laisse choisir la taille, et la taille retenue est reprise dans le devis.\\n\\nIndiquez votre mesure dans le message au moment de l’envoi : nous confirmons la taille avant de chiffrer. Cela vaut la peine même quand la longueur semble sans ambiguïté, car la bonne taille dépend aussi du tour de cuisse, qu’une longueur seule ne dit pas."},"q2":{"q":"Combien de temps dure une séance, et à quelle fréquence ?","a":"Une séance dure normalement vingt à trente minutes. Une fois par jour suffit à la plupart des gens, et juste après l’entraînement est le moment le plus courant.\\n\\nCommencez à la pression la plus basse à laquelle vous sentez encore qu’il se passe quelque chose, et restez-y la première semaine. Une compression inconfortable n’agit pas mieux : l’inconfort est exactement le moment où l’on arrête d’en faire tous les jours, et la régularité vaut davantage que n’importe quelle séance isolée."},"q3":{"q":"Puis-je l’utiliser si j’ai un problème de santé ?","a":"Demandez d’abord à votre médecin. Il s’agit d’un matériel de confort et de récupération, pas d’un dispositif médical, et nous ne sommes pas en mesure de nous prononcer sur une situation que nous ne voyons pas.\\n\\nLa compression est généralement déconseillée en cas de caillot connu ou suspecté, d’infection ou d’inflammation aiguë de la jambe, de fracture non consolidée, d’insuffisance cardiaque ou rénale sévère, ou pendant la grossesse sans avis médical. Si l’un de ces cas vous concerne, ne commandez pas sur la foi de cette page : parlez-en à un professionnel de santé."},"q4":{"q":"Comment commander ? Est-ce que je paie sur ce site ?","a":"Vous ne payez rien sur ce site, et aucune donnée bancaire n’y est collectée.\\n\\nAjoutez les articles qui vous intéressent à votre liste de demande et envoyez-la. Nous répondons avec un devis complet : le matériel, le transport jusqu’à votre adresse, et les droits que nous pouvons établir à l’avance. Les modalités de paiement sont convenues directement avec vous ensuite. Envoyer une demande ne coûte rien et n’engage à rien."},"q5":{"q":"Dans quelle devise sont les prix ?","a":"Les prix sont établis en livres sterling. Vous pouvez afficher la conversion en dollars américains, euros, yuans, yens ou dollars de Hong Kong via le sélecteur en haut de page.\\n\\nCes conversions sont là pour la lecture uniquement, à un taux qui bouge. Le devis, et le montant qui vous sera effectivement demandé, sont en livres sterling."},"q6":{"q":"Comment entretenir les bottes ?","a":"Essuyez l’intérieur avec un chiffon humide après usage et laissez-les sécher ouvertes : ce qui abrège le plus la vie d’un manchon, c’est d’être rangé encore humide.\\n\\nNe les passez pas en machine et jamais au sèche-linge : les chambres sont soudées, et ce sont la chaleur et le tambour qui font lâcher les soudures. Rangez-les enroulées sans serrer plutôt que pliées toujours sur le même pli, et ne laissez jamais les tuyaux pincés sous un objet lourd."},"q7":{"q":"Fournissez-vous les clubs, les cabinets et les salles de sport ?","a":"Oui. Dites-nous combien d’unités il vous faut et comment elles seront utilisées — une salle de kiné et un plateau de musculation ne sont pas le même besoin — et nous chiffrons l’ensemble.\\n\\nPour plusieurs unités, il vaut presque toujours la peine de discuter séparément du nombre d’unités de commande et du nombre de manchons : c’est là que se concentre l’essentiel du coût, et donc de l’économie."},"q8":{"q":"Comment suivre une demande déjà envoyée ?","a":"Chaque demande reçoit un code de référence, visible sur la confirmation à l’envoi et repris dans l’e-mail qui suit.\\n\\nUtilisez « Retrouver ma commande » avec ce code et l’adresse e-mail utilisée, ou connectez-vous si vous avez créé un compte : la page du compte liste chaque demande avec son statut."}}},"ru":{"companyName":"Esva boots","slogan":"Восстановление · Забота · Результат","seoTitle":"Esva boots — сапоги для восстановления и прессотерапии","seoDescription":"Сапоги для прессотерапии при тяжести и усталости в ногах. Последовательная компрессия от щиколотки вверх, сеансы по двадцать минут, размеры по длине внутренней стороны ноги. Полную цену с доставкой мы называем до оплаты.","hero":{"eyebrow":"Recovery in motion","title":"Восстановление мышц — доступно каждому","subtitle":"Сапоги для прессотерапии, которые гонят жидкость из уставших ног снизу вверх примерно за двадцать минут. Оборудование, жившее в кабинете физиотерапии, — по размеру вашей гостиной.","btn1":"Посмотреть линейку","btn2":"Задать вопрос"},"bento":{"title":"От чего зависит, работают ли сапоги","lead":"Три вещи решают, будете ли вы пользоваться ими через месяц.","statLabel":"минут за сеанс"},"products":{"title":"Линейка Esva","lead":"Манжеты на ноги, на руки и блок управления, который их питает."},"caps":{"title":"Три причины этим пользоваться","lead":"Те же двадцать минут — по совершенно разным поводам."},"reviews":{"title":"Отзывы покупателей","lead":"Отзывы тех, кто пользуется нашим оборудованием."},"partners":{"title":"Команды и спортсмены","lead":"Клубы и профессионалы, которые тренируются с Esva boots."},"faq":{"title":"Частые вопросы","lead":"Размеры, сеансы, заказ — то, о чём спрашивают чаще всего."},"inquiry":{"title":"Спрашивайте о чём угодно","lead":"Размеры, сроки, расчёт на несколько комплектов — напишите нам, мы ответим."},"about":{"title":"О Esva boots","content":"Прессотерапия — не новость. Она десятилетиями стоит в кабинетах физиотерапии и в медицинских комнатах профессиональных клубов в виде аппарата, который никто не мог унести домой и который мало кто мог позволить себе арендовать дважды в неделю.\\n\\nEsva boots существует, чтобы закрыть этот разрыв. Та же последовательная компрессия — в оборудовании, которое лежит в шкафу и используется во вторник вечером, по цене, при которой второй сеанс уже ничего не стоит.\\n\\nМы предпочитаем объяснить, чего оборудование не делает, вместо того чтобы преувеличивать то, что оно делает. Компрессия перемещает жидкость и снимает тяжесть. Она не лечит заболевание, и всякому, у кого оно есть, следует сначала поговорить с врачом. Такой ответ стоит нам нескольких продаж и оставляет те, ради которых стоит работать."},"contact":{"address":""},"navText":{"n1":{"title":"Главная"},"n2":{"title":"Товары"},"n3":{"title":"О компании"},"n4":{"title":"Вопросы"},"n5":{"title":"Контакты"}},"highlightText":{"h1":{"title":"Последовательная компрессия","desc":"Камеры надуваются по очереди, от щиколотки вверх: жидкость идёт в одну сторону, а не зажимается с двух концов сразу. Эта последовательность и есть вся разница между прессотерапией и обычным сжатием."},"h2":{"title":"Двадцать минут, а не запись к специалисту","desc":"Достаточно коротко, чтобы сделать после тренировки или вечером на диване. Режим восстановления доживает до третьей недели только если помещается в тот вечер, который у вас действительно есть."},"h3":{"title":"Размеры под реальные ноги","desc":"Сапоги подбираются по длине ноги, а не по размеру обуви и не по росту. Сапог, который заканчивается на середине голени, ничего не сделает для бедра — а именно там скапливается основная тяжесть."}},"capText":{"c1":{"title":"Восстановиться","desc":"Снять тяжесть после длинной пробежки, матча или дня на ногах. Двадцать минут проработки ноги делают то, чего не даёт час с поднятыми ногами."},"c2":{"title":"Показать результат","desc":"Быстрее выходить на следующую тренировку. Восстановление — та часть подготовки, которая незаметно решает, сколько от завтрашнего дня вы реально сможете использовать."},"c3":{"title":"Облегчить","desc":"Для ног, которые тяжелеют каждый вечер: стоячая работа, долгий перелёт или просто конец дня. Это комфорт, а не лечение — см. вопросы ниже."}},"trustText":{"t1":{"title":"Гарантия 2 года","desc":"Блок управления и манжеты."},"t2":{"title":"Доставка по всему миру","desc":"С отслеживанием, пошлины считаем заранее."},"t3":{"title":"30 дней на возврат","desc":"Без следов использования, в оригинальной упаковке."},"t4":{"title":"Сначала расчёт, потом оплата","desc":"На этом сайте ничего не списывается. Пришлите список — ответим полной ценой с доставкой."}},"faqText":{"q1":{"q":"Как выбрать размер?","a":"На странице каждого товара можно выбрать размер, и выбранный размер переносится в расчёт.\\n\\nУкажите свою мерку в сообщении при отправке запроса — мы подтвердим размер до расчёта. Это стоит сделать, даже если длина выглядит однозначной: подходящий размер обычно зависит ещё и от обхвата бедра, о котором одна длина ничего не говорит."},"q2":{"q":"Сколько длится сеанс и как часто его делать?","a":"Сеанс обычно длится двадцать–тридцать минут. Большинству достаточно одного раза в день, и чаще всего это делают сразу после тренировки.\\n\\nНачните с самого низкого давления, при котором всё ещё чувствуется, что что-то происходит, и держитесь его первую неделю. Некомфортная компрессия не работает лучше: дискомфорт — это ровно та точка, после которой человек перестаёт делать процедуру ежедневно, а регулярность стоит больше любого отдельного сеанса."},"q3":{"q":"Можно ли пользоваться при заболеваниях?","a":"Сначала спросите своего врача. Это оборудование для комфорта и восстановления, а не медицинское изделие, и мы не вправе судить о состоянии, которого не видим.\\n\\nКомпрессию, как правило, не применяют при известном или подозреваемом тромбе, острой инфекции или воспалении ноги, несросшемся переломе, тяжёлой сердечной или почечной недостаточности, а также во время беременности без назначения врача. Если что-то из этого относится к вам, не заказывайте, опираясь на эту страницу, — поговорите со специалистом."},"q4":{"q":"Как оформить заказ? Оплата на сайте?","a":"На этом сайте вы ничего не платите, и банковские данные здесь никогда не собираются.\\n\\nДобавьте интересующие товары в список запроса и отправьте его. Мы ответим полным расчётом: оборудование, доставка по вашему адресу и пошлины, которые удастся выяснить заранее. Условия оплаты обсуждаются с вами напрямую уже после. Отправка запроса ничего не стоит и ни к чему не обязывает."},"q5":{"q":"В какой валюте указаны цены?","a":"Цены установлены в фунтах стерлингов. Отображение можно переключить на доллары США, евро, юани, иены или гонконгские доллары — переключатель в шапке страницы.\\n\\nЭто пересчёт только для удобства чтения, по курсу, который меняется. Расчёт и сумма, которую у вас действительно попросят, — в фунтах стерлингов."},"q6":{"q":"Как ухаживать за манжетами?","a":"После использования протрите внутреннюю сторону влажной тканью и дайте высохнуть в раскрытом виде: чаще всего срок службы манжеты сокращает именно то, что её убрали влажной.\\n\\nНе стирайте в машине и не сушите в сушильной машине: камеры сварные, а нагрев и барабан — ровно то, что расходит сварные швы. Храните свободно свёрнутыми, а не сложенными каждый раз по одному и тому же сгибу, и никогда не оставляйте шланги перегнутыми под чем-то тяжёлым."},"q7":{"q":"Поставляете ли вы клубам, клиникам и залам?","a":"Да. Скажите, сколько комплектов нужно и как их будут использовать — кабинет физиотерапии и тренажёрный зал это разные задачи, — и мы посчитаем весь набор.\\n\\nПри нескольких комплектах почти всегда стоит обсудить количество блоков управления отдельно от количества манжет: там и основная часть стоимости, и основная экономия."},"q8":{"q":"Как узнать статус уже отправленного запроса?","a":"У каждого запроса есть код, он показывается на подтверждении сразу после отправки и дублируется в письме.\\n\\nОткройте «Найти заказ», введите этот код и адрес почты, с которого отправляли, либо войдите в аккаунт, если вы его заводили, — на странице аккаунта перечислены все запросы с текущим статусом."}}},"es":{"companyName":"Esva boots","slogan":"Recuperación · Cuidado · Rendimiento","seoTitle":"Esva boots — Botas de recuperación y presoterapia","seoDescription":"Botas de presoterapia para piernas pesadas y cansadas. Compresión secuencial desde el tobillo hacia arriba, sesiones de veinte minutos, tallas según el largo interior de la pierna. Presupuestamos el precio completo con transporte incluido antes de cualquier pago.","hero":{"eyebrow":"Recovery in motion","title":"La recuperación muscular, al alcance de todos","subtitle":"Botas de presoterapia que movilizan el líquido de las piernas cansadas, del tobillo hacia arriba, en unos veinte minutos. El equipo que vivía en la clínica, a la medida de su salón.","btn1":"Ver la gama","btn2":"Hacer una consulta"},"bento":{"title":"Qué hace que una bota de recuperación funcione","lead":"Tres cosas deciden si seguirá usándola dentro de un mes.","statLabel":"minutos por sesión"},"products":{"title":"La gama Esva","lead":"Perneras, manguitos y la unidad de control que los alimenta."},"caps":{"title":"Tres motivos para usarla","lead":"Los mismos veinte minutos, por razones muy distintas."},"reviews":{"title":"Lo que dicen nuestros clientes","lead":"Opiniones de quienes usan nuestros equipos."},"partners":{"title":"Equipos y deportistas","lead":"Clubes y profesionales que entrenan con Esva boots."},"faq":{"title":"Preguntas frecuentes","lead":"Tallas, sesiones, pedidos: lo que más nos preguntan."},"inquiry":{"title":"Pregúntenos lo que sea","lead":"Tallas, plazos, un presupuesto para varias unidades: escríbanos y le respondemos."},"about":{"title":"Sobre Esva boots","content":"La presoterapia no es nada nuevo. Lleva décadas en las clínicas de fisioterapia y en las salas de los equipos profesionales, con la forma de una máquina que nadie podía llevarse a casa y que pocos podían permitirse alquilar dos veces por semana.\\n\\nEsva boots existe para cerrar esa distancia. La misma compresión secuencial, en un equipo que se guarda en un armario y se usa un martes por la noche, a un precio que hace que la segunda sesión no cueste nada.\\n\\nPreferimos explicar lo que el equipo no hace antes que exagerar lo que sí hace. La compresión moviliza líquido y alivia la pesadez; no trata ninguna patología, y quien tenga una debe consultar antes con un médico. Esa respuesta nos cuesta algunas ventas y nos deja las que valen la pena."},"contact":{"address":""},"navText":{"n1":{"title":"Inicio"},"n2":{"title":"Productos"},"n3":{"title":"Sobre nosotros"},"n4":{"title":"Preguntas frecuentes"},"n5":{"title":"Contacto"}},"highlightText":{"h1":{"title":"Compresión secuencial","desc":"Las cámaras se inflan en orden, del tobillo hacia arriba: el líquido se mueve en un solo sentido en vez de quedar prensado por los dos extremos a la vez. Esa secuencia es toda la diferencia entre la presoterapia y un simple apretón."},"h2":{"title":"Veinte minutos, no una cita","desc":"Lo bastante corto para hacerlo después de entrenar, o por la noche en el sofá. Una rutina de recuperación solo pasa de la segunda semana si cabe en la tarde que realmente tiene."},"h3":{"title":"Tallas para piernas reales","desc":"Las botas se eligen por el largo de la pierna, no por el número de calzado ni por la estatura. Una bota que termina a media pantorrilla no puede hacer nada por un muslo, que es donde se acumula casi toda la pesadez."}},"capText":{"c1":{"title":"Recuperar","desc":"Aliviar piernas pesadas tras una tirada larga, un partido o un día de pie. Veinte minutos trabajando la pierna entera hacen lo que una hora con las piernas en alto no hace."},"c2":{"title":"Rendir","desc":"Encadenar más rápido entre sesiones. La recuperación es la parte del entrenamiento que decide, sin hacer ruido, cuánto del día siguiente podrá aprovechar de verdad."},"c3":{"title":"Aliviar","desc":"Para piernas que pesan cada tarde: trabajo de pie, vuelos largos o simplemente el final del día. Confort, no un tratamiento médico: vea las preguntas más abajo."}},"trustText":{"t1":{"title":"Garantía de 2 años","desc":"Unidad de control y perneras."},"t2":{"title":"Envío a todo el mundo","desc":"Con seguimiento y aranceles calculados de antemano."},"t3":{"title":"30 días para cambiar de opinión","desc":"Sin usar y en su embalaje original."},"t4":{"title":"Un presupuesto antes de pagar","desc":"En este sitio no se cobra nada. Envíe su lista y le respondemos con el precio completo, transporte incluido."}},"faqText":{"q1":{"q":"¿Cómo elijo la talla correcta?","a":"Cada ficha de producto le permite elegir la talla, y la talla elegida se arrastra hasta el presupuesto.\\n\\nIndique su medida en el mensaje al enviar la solicitud: confirmamos la talla antes de presupuestar. Merece la pena aunque el largo parezca inequívoco, porque la talla correcta suele depender también del contorno del muslo, que un largo por sí solo no recoge."},"q2":{"q":"¿Cuánto dura una sesión y con qué frecuencia?","a":"Una sesión dura normalmente entre veinte y treinta minutos. Una vez al día basta para la mayoría, y justo después de entrenar es el momento más habitual.\\n\\nEmpiece por la presión más baja en la que aún note que ocurre algo, y quédese ahí la primera semana. Una compresión incómoda no actúa mejor: la incomodidad es exactamente el punto en el que se deja de hacer a diario, y la constancia vale más que cualquier sesión aislada."},"q3":{"q":"¿Puedo usarla si tengo alguna afección médica?","a":"Consulte antes con su médico. Es un equipo de confort y recuperación, no un producto sanitario, y no estamos en posición de opinar sobre una situación que no vemos.\\n\\nLa compresión no suele emplearse cuando hay un coágulo conocido o sospechado, una infección o inflamación aguda de la pierna, una fractura no consolidada, insuficiencia cardiaca o renal grave, ni durante el embarazo sin indicación médica. Si alguno de esos casos le afecta, no compre basándose en esta página: hable con un profesional sanitario."},"q4":{"q":"¿Cómo se hace el pedido? ¿Se paga en este sitio?","a":"En este sitio no se paga nada y nunca se recogen aquí datos bancarios.\\n\\nAñada los artículos que le interesen a su lista de solicitud y envíela. Le respondemos con un presupuesto completo: el equipo, el transporte hasta su dirección y los aranceles que podamos establecer por adelantado. Las condiciones de pago se acuerdan después directamente con usted. Enviar una solicitud no cuesta nada ni compromete a nada."},"q5":{"q":"¿En qué moneda están los precios?","a":"Los precios se fijan en libras esterlinas. Puede cambiar la visualización a dólares estadounidenses, euros, yuanes, yenes o dólares de Hong Kong con el selector de la cabecera.\\n\\nEsas conversiones son solo para leer con comodidad, a un tipo que se mueve. El presupuesto, y la cifra que realmente se le pedirá, van en libras esterlinas."},"q6":{"q":"¿Cómo cuido las botas?","a":"Pase un paño húmedo por el interior después de usarlas y déjelas secar abiertas: lo que más acorta la vida de una pernera es guardarla todavía húmeda.\\n\\nNo las lave a máquina ni las meta en la secadora: las cámaras van soldadas, y el calor y el tambor son justamente lo que revienta las soldaduras. Guárdelas enrolladas sin apretar en vez de dobladas siempre por el mismo pliegue, y no deje nunca los tubos pinzados bajo algo pesado."},"q7":{"q":"¿Suministran a clubes, clínicas y gimnasios?","a":"Sí. Díganos cuántas unidades necesita y cómo se van a usar —una sala de fisioterapia y una sala de musculación no son la misma necesidad— y presupuestamos el conjunto.\\n\\nCon varias unidades casi siempre merece la pena hablar por separado del número de unidades de control y del número de perneras: ahí está la mayor parte del coste y, por tanto, del ahorro."},"q8":{"q":"¿Cómo consulto una solicitud ya enviada?","a":"Cada solicitud recibe un código de referencia, que aparece en la confirmación al enviarla y se repite en el correo posterior.\\n\\nUse «Buscar pedido» con ese código y el correo electrónico desde el que la envió, o inicie sesión si creó una cuenta: la página de la cuenta lista cada solicitud con su estado actual."}}},"ja":{"companyName":"Esva boots","slogan":"リカバリー · ケア · パフォーマンス","seoTitle":"Esva boots — リカバリーブーツと加圧セラピー","seoDescription":"重だるい脚のための加圧式リカバリーブーツ。足首から上へ順に加圧、1 回 20 分、脚の内側の長さでサイズを選びます。お支払いの前に、送料込みの総額をお見積りします。","hero":{"eyebrow":"Recovery in motion","title":"筋肉のリカバリーを、すべての人に","subtitle":"疲れた脚の水分を足首から上へ押し上げる加圧式ブーツ。1 回およそ 20 分。治療院にしかなかった機材を、ご自宅のリビングに収まる大きさで。","btn1":"製品を見る","btn2":"質問する"},"bento":{"title":"リカバリーブーツの良し悪しを決めるもの","lead":"1 か月後もまだ使っているかどうかは、この 3 つで決まります。","statLabel":"分の 1 セッション"},"products":{"title":"Esva のラインアップ","lead":"レッグカフ、アームカフ、そしてそれらを動かす本体。"},"caps":{"title":"使う理由は 3 つ","lead":"同じ 20 分でも、きっかけはずいぶん違います。"},"reviews":{"title":"お客様の声","lead":"実際にご利用いただいた方からの評価です。"},"partners":{"title":"チームとアスリート","lead":"Esva boots とともにトレーニングするクラブとプロ選手。"},"faq":{"title":"よくあるご質問","lead":"サイズ、使い方、ご注文——よくいただくご質問です。"},"inquiry":{"title":"どんなことでもご相談ください","lead":"サイズ、納期、複数台のお見積り——お書きいただければご返信します。"},"about":{"title":"Esva boots について","content":"加圧セラピーは新しいものではありません。理学療法のクリニックやプロチームの治療室で何十年も使われてきました。ただしその姿は、家に持ち帰れず、週に二度借りる余裕のある人もほとんどいない機械でした。\\n\\nEsva boots はその隔たりを埋めるためにあります。同じ順次加圧を、戸棚にしまっておいて火曜の夜に取り出す機材として。2 回目のセッションに費用がかからない価格で。\\n\\nできることを大きく言うより、できないことを先に説明したいと考えています。加圧は水分を動かし、重だるさを和らげます。病気を治すものではありませんし、疾患のある方はまず医師にご相談ください。この答えでいくつかの注文は逃しますが、残るのは残る価値のある注文です。"},"contact":{"address":""},"navText":{"n1":{"title":"ホーム"},"n2":{"title":"製品"},"n3":{"title":"会社概要"},"n4":{"title":"よくあるご質問"},"n5":{"title":"お問い合わせ"}},"highlightText":{"h1":{"title":"順次加圧","desc":"足首から上へ、各エアチャンバーが順番に膨らみます。両端から同時に挟み込むのではなく、水分が一方向へ動く。この「順番」こそが、加圧セラピーとただの圧迫との違いのすべてです。"},"h2":{"title":"20 分。予約は要りません","desc":"トレーニング後にも、夜ソファでも済む長さ。リカバリーの習慣が 2 週目を越えられるかどうかは、実際にある夜の時間に収まるかどうかで決まります。"},"h3":{"title":"実際の脚に合うサイズ","desc":"ブーツは脚の長さで選びます。靴のサイズでも身長でもありません。ふくらはぎの途中で終わるブーツは、太ももには何もできません——重だるさの大半はそこにあります。"}},"capText":{"c1":{"title":"回復する","desc":"長いランの後、試合の後、立ち仕事の一日の後に、重い脚をゆるめる。脚を端から端まで動かす 20 分は、ただ脚を上げて過ごす 1 時間とは別のことをしています。"},"c2":{"title":"走り続ける","desc":"セッションとセッションの間を短くする。リカバリーは、明日どれだけ動けるかを静かに決めている、トレーニングの一部です。"},"c3":{"title":"和らげる","desc":"毎晩重くなる脚のために——立ち仕事、長時間のフライト、あるいは単に一日の終わり。これは快適さのためのもので、治療ではありません。下のご質問をご覧ください。"}},"trustText":{"t1":{"title":"2 年保証","desc":"本体とカフの両方。"},"t2":{"title":"世界中へ配送","desc":"追跡付き。関税は事前にお知らせします。"},"t3":{"title":"30 日以内なら返品可","desc":"未使用・元の梱包のままの場合。"},"t4":{"title":"お見積りが先、お支払いは後","desc":"当サイトでの決済はありません。リストをお送りいただければ、送料込みの総額をお返しします。"}},"faqText":{"q1":{"q":"サイズはどう選べばよいですか。","a":"各製品ページでサイズを選べます。選んだサイズはそのままお見積りに反映されます。\\n\\nリクエストを送る際、メッセージ欄に測った数値をお書きください。お見積りの前にサイズを確認します。長さが明らかに見える場合でも書いていただく価値があります——適切なサイズは太ももの周径にも左右され、長さだけでは分からないためです。"},"q2":{"q":"1 回何分、どのくらいの頻度で使いますか。","a":"1 回は通常 20〜30 分です。ほとんどの方は 1 日 1 回で十分で、トレーニング直後に行う方が最も多くいらっしゃいます。\\n\\n最初の 1 週間は、「何かが起きている」と感じられる最も低い圧に設定したまま続けてください。強すぎる圧が効くわけではありません。不快さはまさに、毎日続けるのをやめてしまう地点であり、続くことのほうが一回一回より価値があります。"},"q3":{"q":"持病がありますが使えますか。","a":"まず主治医にご相談ください。これは快適さとリカバリーのための機材であり、医療機器ではありません。拝見できない状態について、私たちが判断できる立場にはありません。\\n\\n血栓が分かっている・疑われる場合、脚の急性の感染や炎症、癒合していない骨折、重い心不全や腎不全、また医師の指示のない妊娠中は、一般に加圧は行いません。いずれかに当てはまる場合は、このページを根拠にご注文なさらず、医療者にご相談ください。"},"q4":{"q":"注文はどうしますか。このサイトで支払うのですか。","a":"当サイトでお支払いいただくことはありません。カード情報をここで取得することもありません。\\n\\n気になる商品をリクエストリストに入れてお送りください。機材、お届け先までの送料、事前に分かる範囲の関税を含めた完全なお見積りをお返しします。お支払い条件はその後、直接ご相談のうえ決めます。リクエストの送信は無料で、何の義務も生じません。"},"q5":{"q":"価格の通貨は何ですか。","a":"価格は英ポンド建てです。ヘッダーの切り替えで、米ドル・ユーロ・人民元・日本円・香港ドルでの表示に変更できます。\\n\\nこれは読みやすさのための換算にすぎず、レートは変動します。お見積り、および実際にご請求する金額は英ポンドです。"},"q6":{"q":"お手入れはどうすればよいですか。","a":"使用後は内側を湿らせた布で拭き、開いたまま乾かしてください。カフの寿命を縮める原因の多くは、湿ったまましまい込むことです。\\n\\n洗濯機で洗わず、乾燥機にも入れないでください。エアチャンバーは溶着されており、熱と回転はその溶着部を壊すものそのものです。毎回同じ折り目で畳むのではなく、ゆるく丸めて保管し、ホースを重いものの下で折り曲げたままにしないでください。"},"q7":{"q":"クラブ・治療院・ジムへの導入は可能ですか。","a":"可能です。必要な台数と、おおよその使われ方をお知らせください——施術室とジムのフロアでは要件が違います——一式でお見積りします。\\n\\n複数台の場合は、本体の台数とカフの数を分けて相談する価値がほぼ必ずあります。費用の大半はそこにあり、したがって節約できる余地もそこにあります。"},"q8":{"q":"送信済みのリクエストの状況を確認するには。","a":"リクエストごとに参照コードが発行されます。送信直後の確認画面と、その後のメールの両方に記載されています。\\n\\n「注文を探す」でそのコードと送信時のメールアドレスを入力してください。アカウントを作成された場合はログインすると、アカウントページに各リクエストと現在の状況が一覧で表示されます。"}}},"zh":{"companyName":"Esva boots","slogan":"恢复 · 养护 · 表现","seoTitle":"Esva boots —— 空气波恢复靴与加压恢复设备","seoDescription":"面向双腿沉重、疲劳人群的空气波加压恢复靴。气室自踝部向上依次充放，一次二十分钟，按腿内侧长度分码。付款前先出含运费的完整报价。","hero":{"eyebrow":"Recovery in motion","title":"让肌肉恢复，人人都用得上","subtitle":"空气波恢复靴，自踝部向上把疲劳双腿里的体液推回去，一次约二十分钟。原本只在理疗室里的设备，做成你客厅里放得下的样子。","btn1":"看看产品","btn2":"问个问题"},"bento":{"title":"一双恢复靴，好不好用看什么","lead":"三件事决定你一个月后还会不会用它。","statLabel":"分钟一次"},"products":{"title":"Esva 产品线","lead":"腿套、臂套，以及驱动它们的主机。"},"caps":{"title":"三种用它的理由","lead":"同样的二十分钟，起因却很不一样。"},"reviews":{"title":"顾客怎么说","lead":"来自实际使用者的评价。"},"partners":{"title":"合作球队与运动员","lead":"正在用 Esva boots 训练的俱乐部和职业选手。"},"faq":{"title":"常见问题","lead":"尺码、使用、下单——被问得最多的那几个。"},"inquiry":{"title":"有问题随时问","lead":"尺码、交期、多套设备的报价——写给我们，我们会回。"},"about":{"title":"关于 Esva boots","content":"空气波加压并不是什么新东西。它在理疗诊所和职业队的治疗室里待了几十年，形态是一台谁也搬不回家、也很少有人负担得起一周租两次的机器。\\n\\nEsva boots 就是为了补上这个落差。同样的顺序加压，做成一件收在柜子里、周二晚上拿出来用的设备——价格做到让第二次使用不再花钱。\\n\\n比起把它能做的夸大，我们更愿意先说清它不能做什么。加压能推动体液、缓解沉重感，但它不治疗任何疾病；身上有病症的人应当先问医生。这个回答会让我们少卖几单，留下的才是值得留的。"},"contact":{"address":""},"navText":{"n1":{"title":"首页"},"n2":{"title":"产品"},"n3":{"title":"关于我们"},"n4":{"title":"常见问题"},"n5":{"title":"联系我们"}},"highlightText":{"h1":{"title":"梯度顺序加压","desc":"气室自踝部向上按顺序充气，体液朝一个方向走，而不是被两头同时挤住。这个顺序，就是空气波和普通挤压之间的全部差别。"},"h2":{"title":"二十分钟，不用专门跑一趟","desc":"短到练完就能做，或者晚上窝在沙发上做。一套恢复习惯能不能撑过第二周，取决于它塞不塞得进你真正有的那个晚上。"},"h3":{"title":"按真实腿长分码","desc":"靴子按腿内侧长度选，不看鞋码也不看身高。一只到小腿一半就到顶的靴子，对大腿什么也做不了——而沉重感大半就压在大腿上。"}},"capText":{"c1":{"title":"恢复","desc":"长距离跑完、一场比赛之后，或者站了一整天，把沉重的双腿松开。二十分钟把腿从头到尾走一遍，抬腿躺一小时做不到这件事。"},"c2":{"title":"表现","desc":"两次训练之间恢复得更快。恢复是训练里最不起眼、却真正决定明天你能用上多少的那一部分。"},"c3":{"title":"缓解","desc":"给每天傍晚都发沉的那双腿——久站的工作、长途飞行，或者只是到了一天的末尾。这是舒适，不是治疗：见下面的常见问题。"}},"trustText":{"t1":{"title":"两年保修","desc":"主机与腿套。"},"t2":{"title":"全球配送","desc":"全程可查，关税提前报明。"},"t3":{"title":"30 天反悔期","desc":"未使用、原包装完好。"},"t4":{"title":"先报价，后付款","desc":"本站不收任何款项。把清单发过来，我们回一份含运费的完整报价。"}},"faqText":{"q1":{"q":"尺码怎么选？","a":"每个商品页都能选码，你选的码会一路带进报价单。\\n\\n发询价时把量出来的数写在留言框里，我们在报价前替你确认一遍。哪怕长度看着很明确也值得写——合适的码通常还取决于大腿围，而长度一个数说明不了。"},"q2":{"q":"一次做多久？多久做一次？","a":"一次通常二十到三十分钟。多数人一天一次就够，练完立刻做是最常见的时机。\\n\\n第一周把压力调到「还能感觉到在工作」的最低一档，就停在那儿。压得难受并不等于效果更好——难受恰恰是你从此不再天天做的那个点，而坚持下来比任何单独一次都值钱。"},"q3":{"q":"有基础疾病还能用吗？","a":"先问你的医生。这是舒适和恢复用的器材，不是医疗器械，我们也没有立场对看不见的身体状况下判断。\\n\\n已知或疑似血栓、腿部急性感染或炎症、尚未愈合的骨折、严重心衰或肾衰，以及妊娠期未经医嘱，通常都不使用加压。上述任何一条符合，请不要只凭这一页下单，先找医生谈。"},"q4":{"q":"怎么下单？在这个网站上付款吗？","a":"本站不收取任何款项，也从不在这里收集银行卡信息。\\n\\n把感兴趣的商品加进询价清单发过来，我们回一份完整报价：设备、到你地址的运费，以及能提前查清的关税。付款方式之后与你直接商定。发一份询价不花钱，也不构成任何承诺。"},"q5":{"q":"价格是什么币种？","a":"价格以英镑定价。你可以用页首的切换器把显示换成美元、欧元、人民币、日元或港币。\\n\\n那些只是方便阅读的换算，汇率是会动的。报价单以及最终真正向你收取的金额，都是英镑。"},"q6":{"q":"靴子怎么保养？","a":"用完拿湿布擦一遍内衬，摊开晾干——最伤腿套寿命的就是带着潮气直接收起来。\\n\\n不要机洗，更不要进烘干机：气室是热合的，高温和滚筒正好是把热合缝弄开的两样东西。收纳时松松卷起，别每次都沿同一道折痕对折，也不要让气管被重物压出死弯。"},"q7":{"q":"给俱乐部、诊所和健身房供货吗？","a":"供。告诉我们要几套、大致怎么用——理疗室和健身房地面是两种完全不同的需求——我们按整套报。\\n\\n多套的时候，主机的数量和腿套的数量值得分开谈：成本主要压在前者上，能省下的也在那儿。"},"q8":{"q":"已经发出的询价怎么查进度？","a":"每一份询价都有一个参考编号，发送后的确认页上有，随后的邮件里也有。\\n\\n用「查询订单」输入这个编号和当时填的邮箱即可；如果注册过账号，直接登录，账号页会列出每一份询价和它当前的状态。"}}}}}',
    `updatetime` = NOW()
WHERE `sitecode` = 'DLZ2049739702';

-- 确认一下：应当是 1 行，且 JSON 能解开（MySQL 的 JSON_VALID 会替你验一遍）
SELECT `sitecode`, `sitename`, JSON_VALID(`contentjson`) AS json_ok,
       JSON_LENGTH(`contentjson` -> '$.i18n') AS lang_count,
       JSON_UNQUOTE(`contentjson` -> '$.i18n.en.slogan') AS slogan_en
FROM `u_s_siteinfo`
WHERE `sitecode` = 'DLZ2049739702';
